func testAccApihubAttribute_apihubAttributeEnumExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_apihub_attribute" "default" {
  project      = "%{project}"
  location     = "us-central1"
  attribute_id = "%{attribute_id}"
  display_name = "%{display_name}"
  description  = "%{description}"
  scope        = "VERSION"
  data_type    = "ENUM"
  cardinality  = %{cardinality}

  allowed_values {
    id           = "%{first_value_id}"
    display_name = "%{first_value_display_name}"
    description  = "%{first_value_description}"
  }

  allowed_values {
    id           = "value-2"
    display_name = "Value 2"
    description  = "%{second_value_description}"
  }

  allowed_values {
    id           = "%{third_value_id}"
    display_name = "%{third_value_display_name}"
    description  = "%{third_value_description}"
  }
}
`, context)
}

func testAccCheckApihubAttributeDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_apihub_attribute" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(apihub.Product, config)+"projects/{{project}}/locations/{{location}}/attributes/{{attribute_id}}")
			if err != nil {
				return err
			}

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("ApihubAttribute still exists at %s", url)
			}
		}

		return nil
	}
}
